WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.Score, p.CreationDate, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS Rank, COUNT(c.Id) AS CommentCount, p.OwnerUserId FROM Posts AS p LEFT JOIN Comments AS c ON p.Id = c.PostId WHERE p.CreationDate >= (CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR) GROUP BY p.Id, p.Title, p.Score, p.CreationDate, p.OwnerUserId), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, SUM(p.Score) AS TotalScore, COUNT(DISTINCT p.Id) AS PostCount FROM Users AS u JOIN Posts AS p ON u.Id = p.OwnerUserId WHERE u.Reputation > 1000 GROUP BY u.Id, u.DisplayName), CloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReason FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT u.DisplayName, u.TotalScore, u.PostCount, rp.PostId, rp.Title, rp.Score, rp.Rank, COALESCE(cr.CloseReason, 'No Closure') AS ClosureDetails, CASE WHEN rp.CommentCount = 0 THEN 'No Comments' ELSE CONCAT(COALESCE(rp.CommentCount, ''), ' Comments') END AS CommentsStatus FROM TopUsers AS u JOIN RankedPosts AS rp ON u.UserId = rp.OwnerUserId LEFT JOIN CloseReasons AS cr ON rp.PostId = cr.PostId WHERE rp.Rank <= 5 ORDER BY u.TotalScore DESC NULLS FIRST, rp.Score DESC NULLS FIRST